def sigma_linear(n: int) -> int:
    if n <= 0:
        return 0
    s = 0
    for d in range(1, n + 1):
        if n % d == 0:
            s += d
    return s

def sigma_sqrt(n: int) -> int:
    if n <= 0:
        return 0
    s = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            s += d
            if d * d != n:
                s += n // d
        d += 1
    return s
